import org.formasaloido.*;
import java.util.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;

public final class TeachingChecks {
 static int checks;
 static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static void rejected(Map<String,Object> document,String message){try{MathTeaching.load(Json.write(document));throw new AssertionError(message);}catch(IllegalArgumentException expected){checks++;}}
 static MathTeaching sample(){MathTeaching book=new MathTeaching(new MathLesson("2x+3=11"));book.title="Igualdad: conservar el equilibrio";book.feedback="Profesor: anota aquí qué explicación cambiarías o qué paso falta.";book.mode=5;book.position=0;book.plane=4;book.x=0;book.y=-2;book.put(book.fragment(5,0),"La igualdad como equilibrio","Los dos miembros deben representar el mismo valor. Antes de avanzar, identifica el signo igual y los dos miembros.","Pregunta qué ocurriría si sólo modificáramos un lado.","");book.put(book.fragment(5,book.readings.get("development").size()-2),"Comprobar antes de terminar","Sustituye el valor encontrado en los dos miembros de la ecuación original y compara los resultados.","Dos por cuatro más tres da once.","");book.put("plane:4","Una parábola de ejemplo","Esta gráfica es una exploración independiente de la ecuación lineal. Tiene un mínimo en equis cero, ye menos dos.","Recorre sus puntos desde el extremo izquierdo.","");book.put(MathTeaching.pointTarget(4,0,-2),"Punto mínimo","Desde este punto la curva sube hacia ambos lados.","Compara un punto a la izquierda con otro a la derecha.","");return book;}
 public static void main(String[] args)throws Exception {
  MathTeaching original=sample();MathTeaching restored=MathTeaching.load(original.json());check(restored.json().equals(original.json()),"Deterministic roundtrip");check(restored.note("plane:4",1).contains("independiente"),"Plane annotations");check(restored.note(MathTeaching.pointTarget(4,0,-2),0).equals("Punto mínimo"),"Coordinate anchor");check(restored.describeTarget("fragment:5:0").equals("Pizarra progresiva, fragmento 1"),"Human-readable fragment anchor");check(restored.describeTarget("point:4:0:-20").contains("menos dos"),"Human-readable coordinate anchor");check(MathTeaching.pointTarget(4,-.05,0).equals("point:4:0:0"),"Portable half-step rounding");check(restored.mode==5&&restored.position==0&&restored.y==-2,"Restored cursor");restored.put(restored.fragment(5,0),"Nombre","Texto <script>sin ejecutar</script>","Pista","No entiendo este cambio. Ñ á π");check(MathTeaching.load(restored.json()).note(restored.fragment(5,0),3).contains("Ñ á π"),"Unicode feedback roundtrip");check(restored.note("plane:0",0).contains("No hay"),"Missing note explicit");check(!restored.json().contains("mathVoice")&&!restored.json().contains("volume"),"No forced voice preferences");
  restored.readings.get("development").set(1,"Etapa elegida por el profesor: restamos tres en ambos miembros.");check(MathTeaching.load(restored.json()).readings.get("development").get(1).equals(restored.readings.get("development").get(1)),"Authored progression preserved, not regenerated");check(((Map<?,?>)restored.data().get("exercise")).get("development").equals(restored.readings.get("development")),"Desktop receives frozen progression");
  Map<String,Object> invalid=original.document();invalid.put("schema","formas-lesson-v99");rejected(invalid,"Unknown version");invalid=original.document();invalid.put("title",null);rejected(invalid,"Missing title");invalid=original.document();invalid.put("cursor",Json.object("mode",5,"position",999,"plane",4,"x",0,"y",0));rejected(invalid,"Cursor outside stages");invalid=original.document();invalid.put("cursor",Json.object("mode",0.5,"position",0,"plane",4,"x",0,"y",0));rejected(invalid,"Fractional mode");invalid=original.document();invalid.put("cursor",Json.object("mode",5,"position",0,"plane",99,"x",0,"y",0));rejected(invalid,"Unknown scene");invalid=original.document();invalid.put("notes",Json.object("fragment:5:999",Json.object("name","a","description","b","hint","c","comment","d")));rejected(invalid,"Bad anchor");invalid=original.document();invalid.put("notes",Json.object("point:4:60:0",Json.object("name","a","description","b","hint","c","comment","d")));rejected(invalid,"Point outside canvas");invalid=original.document();invalid.put("feedback","control\u0001");rejected(invalid,"Control character");invalid=original.document();invalid.put("expression","1/0");rejected(invalid,"Invalid operation");
  try{original.put("fragment:5:0","",String.join("",Collections.nCopies(3001,"a")),"","");throw new AssertionError("Oversized annotation");}catch(IllegalArgumentException expected){checks++;}
  String oversized=String.join("",Collections.nCopies(MathTeaching.MAX_BYTES+1," "));try{MathTeaching.load(oversized);throw new AssertionError("Oversized input");}catch(IllegalArgumentException expected){checks++;}
  if(args.length==1){Path directory=Paths.get(args[0]);Files.createDirectories(directory);Files.write(directory.resolve("ecuacion-con-anotaciones.fao"),sample().json().getBytes(StandardCharsets.UTF_8));MathTeaching fractions=new MathTeaching(new MathLesson("1/2+1/3"));fractions.title="Fracciones: hacer comparables las partes";fractions.put(fractions.fragment(5,0),"Primero, entender las partes","Una mitad y un tercio no tienen el mismo tamaño de parte. Por eso buscamos una unidad común.","Imagina dividir ambas unidades en seis partes iguales.","");fractions.put(fractions.fragment(5,3),"Mismo denominador","Tres sextos más dos sextos son cinco sextos. Conservamos el tamaño de las partes y sumamos sus cantidades.","El denominador no se suma.","");Files.write(directory.resolve("fracciones-con-anotaciones.fao"),fractions.json().getBytes(StandardCharsets.UTF_8));}
  System.out.println("PASS "+checks+" teaching checks: authored stages, coordinate/fragment anchors, feedback, inert text, cursor, bounds and portable FAO roundtrip.");
 }
}
